// One-off: wire up a REAL Instagram connection using a token generated by hand on the Meta dashboard
// (Login configuration > Generate token), instead of going through our OAuth "Connect Instagram" button.
// Token is read from an env var, not an argument, so it never lands in shell history.
//
// Usage (PowerShell), run from the project root:
//   $env:IG_TOKEN = "EAA..."; node --env-file=.env.local --experimental-strip-types scripts/add-connection.mjs "<org name>" <igId> <username>
//
// Safe to re-run: upserts by igId, so re-running with a fresh token just updates it.
import { MongoClient } from "mongodb";
import { seal } from "../lib/secrets.ts";

const [orgName, igId, username] = process.argv.slice(2);
const token = process.env.IG_TOKEN;
if (!orgName || !igId || !username || !token) {
  console.error('Usage: $env:IG_TOKEN = "..."; node --env-file=.env.local --experimental-strip-types scripts/add-connection.mjs "<org name>" <igId> <username>');
  process.exit(1);
}

const client = await new MongoClient(process.env.MONGODB_URI).connect();
const db = client.db();
const org = await db.collection("orgs").findOneAndUpdate(
  { name: orgName },
  { $setOnInsert: { name: orgName, createdAt: new Date() } },
  { upsert: true, returnDocument: "after" },
);
await db.collection("botConnections").updateOne(
  { igId },
  { $set: { orgId: org._id, igId, username, token: seal(token), connectedAt: new Date(), subscribed: false }, $unset: { test: "", lastError: "" } },
  { upsert: true },
);
console.log(`Connected @${username} (${igId}) to org "${orgName}".`);
await client.close();
